  "El procesamiento de Nodus Protect es local. No envía tus documentos a IA, proveedores ni servicios externos.": "Nodus Koruma işlemi yereldir. Belgelerinizi yapay zekaya, satıcılara veya harici hizmetlere göndermez.",
