  "Válido únicamente a efectos de identificación en el trámite indicado. No constituye firma, autorización contractual ni consentimiento para usos distintos.": "Yalnızca belirtilen prosedürde tanımlama amacıyla geçerlidir. Farklı kullanımlara yönelik bir imza, sözleşmeye dayalı yetki veya rıza teşkil etmez.",
