  "{count} ocultaciones o desenfoques añadidos. Revisa todas las páginas antes de continuar.": "{count} örtülmeler veya bulanıklıklar eklendi. Devam etmeden önce tüm sayfaları inceleyin.",
  "Área": "Alan",
  "Crea herramientas para investigar, estudiar o enseñar con IA; adáptalas hablando y compártelas por QR.": "Yapay zeka ile araştırma yapmak, çalışmak veya öğretmek için araçlar oluşturun; konuşarak uyarlayın ve QR aracılığıyla paylaşın.",
