  "Describe una necesidad de estudio, docencia o investigación. La IA construye la app, tú la pruebas y puedes pedir cambios con tus propias palabras.": "Çalışma, öğretme veya araştırma ihtiyacını açıklar. Yapay zeka uygulamayı oluşturur, siz test edersiniz ve kendi kelimelerinizle değişiklik talebinde bulunabilirsiniz.",
