  "Para estudiar": "çalışmak",
  "Para investigar": "Araştırmak için",
  "Para enseñar": "öğretmek",
  "Para un grupo": "bir grup için",
  "Una app de repaso activo para preparar un examen: preguntas y respuestas creadas por mí, sesiones cortas y una lista de conceptos que necesito volver a revisar.": "Sınava hazırlanmak için aktif bir inceleme uygulaması: tarafımdan oluşturulan sorular ve cevaplar, kısa oturumlar ve tekrar incelemem gereken kavramların listesi.",
  "Una matriz para comparar artículos académicos por pregunta, método, muestra, hallazgo, limitaciones y relación con mi investigación. Debe guardar los datos y permitir buscar y filtrar.": "Akademik makaleleri soru, yöntem, örnek, bulgu, sınırlamalar ve araştırmamla olan ilişkisine göre karşılaştıracak bir matris. Verileri kaydetmeli ve arama ve filtrelemeye izin vermelidir.",
  "Un planificador de seminarios que reparta el tiempo entre explicación, trabajo individual, discusión y cierre, y avise si la sesión supera la duración disponible.": "Süreyi açıklama, bireysel çalışma, tartışma ve kapanış arasında bölüştüren ve oturumun mevcut süreyi aşması durumunda bildirimde bulunan bir seminer planlayıcısı.",
  "Una actividad por QR para que un grupo responda de forma anónima a una pregunta y el anfitrión vea un resumen en directo sin calificar ni identificar a nadie.": "Bir grubun bir soruya anonim olarak yanıt vermesine yönelik bir QR etkinliği ve toplantı sahibi, kimseyi nitelendirmeden veya kimliğini belirlemeden canlı bir özet görür.",
  "Mejora la app hablando con la IA": "Yapay zeka ile konuşarak uygulamayı geliştirin",
  "Cuéntanos qué necesitas": "Bize neye ihtiyacınız olduğunu söyleyin",
  "No necesitas saber programar.": "Programlamayı bilmenize gerek yok.",
  "Puedes empezar con una frase. La IA se ocupará de la estructura, el diseño y el funcionamiento.": "Bir cümleyle başlayabilirsiniz. Yapay zeka yapı, tasarım ve operasyonla ilgilenecek.",
  "Esta es la versión actual. Pide un cambio concreto o explica qué te resulta difícil.": "Bu güncel versiyondur. Belirli bir değişiklik isteyin veya sizin için neyin zor olduğunu açıklayın.",
  "¿Qué quieres cambiar?": "Neyi değiştirmek istiyorsunuz?",
  "¿Qué debería hacer la app?": "Uygulama ne yapmalı?",
  "Ej. Simplifica la pantalla inicial y añade un filtro por fecha…": "Örneğin. Başlangıç ​​ekranını basitleştirin ve tarihe göre filtre ekleyin…",
  "Ej. Necesito organizar las fuentes de mi trabajo final y comparar sus conclusiones…": "Mesela son çalışmamın kaynaklarını düzenleyip sonuçlarını karşılaştırmam gerekiyor…",
