  "Preparando tu versión…": "Sürümünüz hazırlanıyor…",
  "Aplicar el cambio con IA": "Değişikliği AI ile uygulayın",
  "Crear la app con IA": "Uygulamayı AI ile oluşturun",
  "La app se ejecuta aislada, sin acceso a Internet, archivos, credenciales ni datos de Nodus.": "Uygulama, İnternet erişimi, dosyalar, kimlik bilgileri veya Nodus verileri olmadan izole bir şekilde çalışır.",
  "Prueba la nueva versión. Si algo no encaja, pide otro cambio.": "Yeni sürümü deneyin. Bir şey uymuyorsa başka bir değişiklik isteyin.",
  "Prueba la app actual y describe cualquier mejora con tus palabras.": "Mevcut uygulamayı deneyin ve kelimelerinizle ilgili iyileştirmeleri açıklayın.",
  "En ejecución": "Koşma",
  "La IA preparará una primera versión": "Yapay zeka ilk versiyonu hazırlayacak",
  "Podrás utilizarla aquí mismo y seguir pidiendo cambios hasta que se adapte a ti.": "Hemen burada kullanabilir ve size uygun olana kadar değişiklik istemeye devam edebilirsiniz.",
  "Usar esta versión": "Bu sürümü kullan",
