  "Guarda sus datos": "Verilerinizi kaydedin",
  "Ejecución aislada": "İzole yürütme",
  "Usar app": "Uygulamayı kullan",
  "Compartir por QR": "QR ile paylaş",
  "{name} — copia": "{name} — kopyala",
  "Eliminar app": "Uygulamayı sil",
  "Se eliminará «{name}» y sus datos guardados en Nodus Apps. Esta acción no se puede deshacer.": "“{name}” ve Nodus Uygulamalarında kayıtlı verileriniz silinecek. Bu eylem geri alınamaz.",
  "Corrige este error de la app y comprueba todas sus interacciones: {error}": "Bu uygulama hatasını düzeltin ve tüm etkileşimlerini kontrol edin: {error}",
  "App: {name}": "Uygulama: {name}",
  "Error dentro de la app.": "Uygulama içinde hata.",
