  "Reparar con IA": "AI ile onarım",
  "Comparte la app por QR": "Uygulamayı QR aracılığıyla paylaşın",
  "Las personas conectadas a tu misma red podrán abrir esta app en su navegador.": "Aynı ağınıza bağlı kişiler bu uygulamayı tarayıcılarında açabilecektir.",
  "Esta app comparte cambios en directo.": "Bu uygulama değişiklikleri canlı olarak paylaşıyor.",
