  "Con más de 6 criterios la rúbrica se vuelve difícil de aplicar en clase.": "6'dan fazla kriterin olması, değerlendirme listesinin sınıfta uygulanması zorlaşır.",
  "Más de 5 niveles aparenta una precisión que no se sostiene al corregir.": "5'ten fazla seviye, düzeltme sırasında sürdürülemeyen hassasiyet görünümü verir.",
  "Este criterio parece un requisito de entrega, no una cualidad del trabajo.": "Bu kriter işin niteliği değil, teslimat şartı gibi görünüyor.",
  "Este criterio junta dos aspectos: sepáralos para poder evaluarlos por separado.": "Bu kriter iki unsuru bir araya getirir: Bunları ayrı ayrı değerlendirebilmek için ayırın.",
  "Este descriptor solo emite un juicio: describe qué hace el trabajo.": "Bu tanımlayıcı yalnızca bir yargıya varır: İşin ne yaptığını açıklar.",
  "Este descriptor describe carencias: redáctalo en positivo, por lo que el trabajo sí hace.": "Bu tanımlayıcı eksiklikleri tanımlar: Olumlu yazın, böylece iş başarılı olur.",
  "Estos dos niveles solo se diferencian en matices: ¿qué hace distinto el trabajo?": "Bu iki düzey yalnızca nüanslarda farklılık gösterir: işi farklı kılan nedir?",
