  "{name} copia": "{name} kopyala",
  "Reutilizar claves de IA de otra bóveda": "Başka bir kasadaki AI anahtarlarını yeniden kullanın",
  "No reutilizar": "Tekrar kullanmayın",
  "Renombrar bóveda": "Kasayı yeniden adlandır",
  "Duplicar bóveda": "Yinelenen kasa",
  "Se creará una copia de «{name}» con todos sus datos.": "“{name}” dosyasının tüm verileriyle birlikte bir kopyası oluşturulacak.",
  "Nombre de la copia": "Adı kopyala",
  "Bóveda duplicada con sus datos y claves API.": "Verileriniz ve API anahtarlarınızla kasayı çoğaltın.",
  "sin claves": "anahtarsız",
  "Las claves de API y los modelos configurados se comparten entre todas tus bóvedas.": "API anahtarları ve yapılandırılmış modeller tüm kasalarınız arasında paylaşılır.",
  "comprobando…": "kontrol ediliyor…",
  "suscripción conectada": "bağlı abonelik",
  "sin conectar": "bağlantısız",
  "Conexión mediante el protocolo oficial Codex App Server y el acceso gestionado de ChatGPT. Nodus no lee ni almacena tus credenciales.": "Resmi Codex Uygulama Sunucusu protokolü ve ChatGPT tarafından yönetilen erişim aracılığıyla bağlantı. Nodus kimlik bilgilerinizi okumaz veya saklamaz.",
  "Nodus es una aplicación independiente y no está afiliada, certificada ni respaldada por OpenAI.": "Nodus bağımsız bir uygulamadır ve OpenAI'ye bağlı değildir, onaylanmamıştır veya onaylanmamıştır.",
  "El uso consume la cuota o los créditos de Codex incluidos en tu plan de ChatGPT; no consume saldo de la API de OpenAI.": "Kullanım, ChatGPT planınıza dahil olan kotayı veya Codex kredilerini tüketir; OpenAI API bakiyesini tüketmez.",
  "Funciona como motor de Nodi, análisis y Deep Research de Nodus. No es el producto Deep Research de la web de ChatGPT.": "Nodi motoru, analizi ve Nodus'un Derin Araştırması olarak çalışır. ChatGPT web sitesindeki Deep Research ürünü değildir.",
  "Cada petición usa un hilo efímero aislado, sin acceso de escritura, sin red de herramientas y sin cargar tus MCP, plugins o instrucciones personales.": "Her istek, yazma erişimi olmayan, araç ağı olmayan ve MCP'lerinizi, eklentilerinizi veya kişisel talimatlarınızı yüklemeyen, izole edilmiş geçici bir iş parçacığı kullanır.",
  "Documentación oficial de Codex App Server ↗": "Resmi Codex Uygulama Sunucusu Belgeleri ↗",
  "Conectado": "Bağlı",
  "Actualizar estado": "Güncelleme durumu",
  "Límite principal": "Ana sınır",
  "Límite secundario": "İkincil sınır",
  "Cargar modelos de Codex": "Codex Modellerini Yükle",
  "Cada modelo muestra únicamente los niveles de razonamiento publicados por Codex. Lo que elijas aquí es el predeterminado del modelo: cada tarea puede fijar el suyo propio en Modelos.": "Her model yalnızca Codex'in yayınladığı akıl yürütme düzeylerini gösterir. Burada seçtiğiniz, modelin varsayılanıdır: her görev kendi düzeyini Modeller içinde belirleyebilir.",
  "Nivel de razonamiento de esta tarea. Menos razonamiento responde antes y solo afecta a esta tarea, aunque otras usen el mismo modelo.": "Bu görevin akıl yürütme düzeyi. Daha az akıl yürütme daha hızlı yanıt verir ve başka görevler aynı modeli kullansa bile yalnızca bu görevi etkiler.",
  "Razonamiento de {model}": "{model} gerekçesi",
