  "Sin créditos": "Kredi yok",
  "{n}% restante": "%{n} kaldı",
  "{n}% usado": "%{n} kullanıldı",
  "SDK oficial · preview": "Resmi SDK önizlemesi",
  "Nodus usa el SDK y el runtime oficiales de GitHub Copilot. Cada petición se factura a la suscripción de GitHub del usuario; no requiere claves de los modelos.": "Nodus, resmi GitHub Copilot SDK'sını ve çalışma zamanını kullanır. Her istek kullanıcının GitHub aboneliğine fatura edilir; model anahtarları gerektirmez.",
  "La integración oficial está en public preview. Nodus es independiente y no está afiliada, certificada ni respaldada por GitHub.": "Resmi entegrasyon genel önizleme aşamasındadır. Nodus bağımsızdır ve GitHub'a bağlı değildir, GitHub tarafından onaylanmamıştır veya onaylanmamıştır.",
  "Cada petición se ejecuta en una sesión efímera sin herramientas, MCP, memoria, acceso a archivos, GitHub ni instrucciones del proyecto.": "Her istek, araçlar, MCP, bellek, dosya erişimi, GitHub veya proje talimatları olmadan geçici bir oturumda yürütülür.",
  "Documentación oficial del SDK de Copilot ↗": "Resmi Copilot SDK Belgeleri ↗",
  "Actualizar cuota": "Kotayı güncelle",
  "GitHub no devolvió un contador de cuota para esta cuenta.": "GitHub bu hesap için kota sayacı döndürmedi.",
  "Última petición en Nodus: {cost} créditos/solicitudes premium · {input} tokens de entrada · {output} de salida": "Nodus'taki son istek: {cost} kredi/premium istek · {input} giriş jetonu · {output} çıktı",
  "Cargar modelos de Copilot": "Yardımcı Pilot Modellerini Yükle",
  "Esperando acceso de GitHub en el navegador…": "Tarayıcıda GitHub erişimi bekleniyor…",
  "Conectar GitHub Copilot": "GitHub Copilot'u bağlayın",
  "El runtime oficial abre el flujo OAuth de dispositivo y guarda su credencial en el almacén seguro del sistema. Si ya usas GitHub CLI, puede reutilizar esa sesión sin modificarla.": "Resmi çalışma zamanı, cihazın OAuth akışını açar ve kimlik bilgilerini sistemin güvenli deposuna kaydeder. GitHub CLI'yi zaten kullanıyorsanız, o oturumu değiştirmeden yeniden kullanabilirsiniz.",
  "Créditos / solicitudes premium": "Premium krediler/talepler",
  "Ilimitado según GitHub": "GitHub'a göre sınırsız",
  "{remaining} de {total} restantes · {used} usadas": "{remaining} / {total} kaldı · {used} kullanıldı",
  "{n} de uso adicional": "Ek kullanım için {n}",
  "OpenCode documenta el uso directo de la suscripción Go mediante esta clave y sus endpoints oficiales. Nodus es independiente y no está afiliada, certificada ni respaldada por OpenCode.": "OpenCode, bu anahtarı ve resmi uç noktalarını kullanarak Go aboneliğinin doğrudan kullanımını belgeliyor. Nodus bağımsızdır ve OpenCode'a bağlı değildir, OpenCode tarafından onaylanmamıştır veya onaylanmamıştır.",
  "Límites generales publicados: 12 USD cada 5 horas, 30 USD por semana y 60 USD por mes. Algunos modelos tienen un límite mensual efectivo inferior (15 USD); el número de peticiones depende del modelo y puede cambiar.": "Belirtilen genel limitler: 5 saatte 12 ABD doları, haftada 30 ABD doları ve ayda 60 ABD doları. Bazı modellerin geçerli aylık limiti daha düşüktür (15$); İstek sayısı modele bağlıdır ve değişebilir.",
  "Saldo restante oficial: OpenCode solo lo publica en Console; no ofrece una API de cuota compatible con la clave de usuario. Nodus no usa cookies ni endpoints privados.": "Resmi Kalan Bakiye: OpenCode bunu yalnızca Konsolda yayınlar; kullanıcı anahtarı uyumlu bir kota API'si sunmamaktadır. Nodus çerezleri veya özel uç noktaları kullanmaz.",
  "Últimas 5 horas": "Son 5 saat",
  "Últimos 7 días": "Son 7 gün",
  "Últimos 30 días": "Son 30 gün",
  "El gasto observado es una estimación local de las peticiones hechas por Nodus con precios oficiales; no incluye otros clientes y no equivale al saldo restante.": "Gözlemlenen harcama, Nodus tarafından yapılan taleplerin resmi fiyatlarla yerel bir tahminidir; diğer müşterileri kapsamaz ve kalan bakiyeye eşdeğer değildir.",
  "Ver saldo restante oficial en OpenCode Console ↗": "OpenCode Konsolunda resmi kalan bakiyeyi görüntüleyin ↗",
  "Documentación oficial de OpenCode Go ↗": "Resmi OpenCode Go Belgeleri ↗",
  "{requests} peticiones · ~${spent} observados · ${cap} de tope general de referencia": "{requests} istek · ~${spent} gözlemlendi · ${cap} genel referans sınırı",
  "{n} sin precio estimable": "Tahmini fiyat olmadan {n}",
  "Anthropic no permite que aplicaciones de terceros ofrezcan inicio de sesión de Claude.ai ni utilicen credenciales de suscripciones Free, Pro o Max. Por ello Claude se conecta aquí únicamente mediante la API oficial.": "Anthropic, üçüncü taraf uygulamaların Claude.ai girişi sunmasına veya Ücretsiz, Pro veya Maksimum abonelik kimlik bilgilerini kullanmasına izin vermez. Bu nedenle Claude buraya yalnızca resmi API aracılığıyla bağlanıyor.",
  "Política oficial de Anthropic ↗": "Resmi İnsan Politikası ↗",
  "Nodus ha encontrado claves de API cifradas que todavía no puede leer.": "Nodus henüz okuyamadığı şifrelenmiş API anahtarlarını buldu.",
  "No se han borrado. Pulsa recuperar y autoriza el acceso al Llavero de macOS si el sistema lo solicita.": "Silinmediler. Sistem isterse kurtar'a basın ve macOS Anahtar Zinciri'ne erişim izni verin.",
  "Claves recuperadas y protegidas de nuevo correctamente.": "Anahtarlar yeniden doğru şekilde kurtarıldı ve korundu.",
  "Algunas claves siguen bloqueadas. Vuelve a intentarlo y acepta el acceso al Llavero.": "Bazı tuşlar hâlâ kilitli. Lütfen tekrar deneyin ve Anahtarlık erişimini kabul edin.",
  "Recuperando…": "Kurtarılıyor…",
  "Recuperar claves": "Anahtarları kurtar",
  "Lo básico queda separado de los parámetros técnicos de análisis y extracción.": "Temel bilgiler, analiz ve ekstraksiyonun teknik parametrelerinden ayrılmıştır.",
