  "El idioma de los prompts determina en qué idioma la IA genera ideas, temas, narrativa del tutor y borradores. Las citas textuales siempre conservan el idioma original de la fuente.": "Bilgi istemlerinin dili, yapay zekanın fikirleri, konuları, öğretmen anlatımını ve taslakları hangi dilde oluşturacağını belirler. Metinsel alıntılar her zaman kaynağın orijinal dilini korur.",
