  "El motor, el modelo y sus descargas se gestionan aquí. Los motores locales trabajan fuera del hilo de la interfaz y no envían el audio a terceros.": "Motor, model ve indirme işlemleri burada yönetilir. Yerel motorlar arayüz iş parçacığının dışında çalışır ve üçüncü taraflara ses göndermez.",
