  "Lo básico: sincronizar, escanear y moverte por el grafo.": "Temel bilgiler: grafiği senkronize edin, tarayın ve hareket ettirin.",
  "Ver de nuevo": "Tekrar gör",
  "Tutorial avanzado de investigación": "İleri Araştırma Eğitimi",
  "El flujo completo: leer con criterio, comprender el corpus, encontrar tu aportación y escribir.": "Akışın tamamı: dikkatli okuyun, metni anlayın, katkınızı bulun ve yazın.",
  "Empezar": "Başlayın",
  "Actualizaciones": "Güncellemeler",
