  "Abrir": "Açık",
  "huecos": "boşluklar",
  "Convierte ideas, contradicciones, huecos y rutas del Tutor en un borrador con citas verificables.": "Fikirleri, çelişkileri, boşlukları ve Eğitmen rotalarını doğrulanabilir alıntılarla bir taslağa dönüştürün.",
  "Configuración IA": "Yapay Zeka Ayarları",
  "modelo predeterminado": "varsayılan model",
  "{n} obras por indexar": "{n} dizine eklenmek için çalışıyor",
  "storage no configurado": "depolama yapılandırılmadı",
  "La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.": "Senkronizasyon işe yarayabilir ancak Nodus'un temaları, fikirleri ve kanıtları çıkarmak için önceden belirlenmiş bir modele ihtiyacı vardır.",
  "Sincroniza Zotero para crear el corpus": "Korpusu oluşturmak için Zotero'yu senkronize edin",
  "Todavía no hay obras locales. Revisa las colecciones monitorizadas y ejecuta una sincronización para poblar la biblioteca.": "Henüz yerel bir çalışma yok. İzlenen koleksiyonları inceler ve kitaplığı doldurmak için bir senkronizasyon gerçekleştirir.",
  "Sincronizar ahora": "Şimdi senkronize et",
  "Completa el análisis ligero": "Işık analizini tamamlayın",
  "El primer resultado visible del mapa depende de los temas extraídos a partir de título y resumen. Analiza temas antes de profundizar.": "Haritanın ilk görünür sonucu, başlık ve özetten çıkarılan konulara bağlıdır. Daha derine inmeden önce konuları analiz edin.",
  "Analizar temas": "Konuları analiz edin",
  "Ver grafo": "Grafiği görüntüle",
  "Extrae ideas de las obras clave": "Önemli çalışmalardan fikir alın",
  "El grafo ya puede orientarte por temas; el siguiente salto de valor llega al analizar a fondo las obras leídas o seleccionadas.": "Grafik artık konulara göre size yol gösterebilir; Değerdeki bir sonraki sıçrama, okunan veya seçilen eserlerin derinlemesine analiz edilmesiyle gerçekleşir.",
  "Analizar ideas": "Fikirleri analiz edin",
  "Indexa embeddings pendientes": "Dizin bekleyen yerleştirmeler",
  "Hay ideas extraídas sin índice semántico. Indexarlas mejora la fusión, las relaciones y el descubrimiento de puentes.": "Anlamsal bir indeks olmadan çıkarılan fikirler var. Bunları indekslemek füzyonu, ilişkileri ve köprülerin keşfedilmesini geliştirir.",
  "Ver ideas": "Fikirleri görün",
  "Convierte el grafo en escritura": "Grafiği yazıya dönüştürür",
  "Ya hay suficientes ideas y fuentes para montar un estado de la cuestión, un marco teórico o una justificación de hueco con citas verificables.": "Doğrulanabilir alıntılarla en son teknolojiyi, teorik bir çerçeveyi veya boşluk gerekçesini bir araya getirmeye yetecek kadar fikir ve kaynak zaten mevcut.",
  "Abrir taller": "Açık atölye",
  "Ver huecos": "Boşlukları görün",
  "Revisa huecos y contradicciones": "Boşlukları ve çelişkileri kontrol edin",
  "El corpus ya tiene material interpretativo. El siguiente paso útil es convertir huecos y tensiones en una ruta de lectura o pregunta de investigación.": "Derlem zaten yorumlayıcı materyale sahiptir. Bir sonraki yararlı adım, boşlukları ve gerginlikleri bir okuma yoluna veya araştırma sorusuna dönüştürmektir.",
  "Explora el grafo con el Tutor": "Grafiği Öğretmenle birlikte keşfedin",
  "El corpus está en buen estado para una lectura guiada. Abre el grafo o pregunta al asistente con el contexto completo.": "Külliyat rehberli okuma için iyi durumdadır. Grafiği açın veya asistana tüm bağlamı sorun.",
  "ligero": "ışık",
