  "Aún no hay etiquetas guardadas. Pulsa “Actualizar” para leer las etiquetas de las colecciones monitorizadas en Zotero.": "Henüz kayıtlı etiket yok. Zotero'da izlenen koleksiyonların etiketlerini okumak için “Yenile” tuşuna basın.",
  "No hay etiquetas que coincidan.": "Eşleşen etiket yok.",
