  "Temas principales": "Ana temalar",
  "Los temas principales son los grandes nodos que agrupan tus ideas en el grafo. Añade los tuyos para controlarlos manualmente; mientras estén bloqueados, los análisis solo usarán estos temas y no generarán otros nuevos.": "Ana temalar, fikirlerinizi grafikte gruplandıran büyük düğümlerdir. Bunları manuel olarak kontrol etmek için kendinizinkini ekleyin; Kilitliyken analizler yalnızca bu konuları kullanacak ve yenilerini oluşturmayacaktır.",
