  "1. Plantea la idea": "1. Fikri ortaya koyun",
  "Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "Geliştirmek istediğiniz araştırma sorusunu veya fikrini yazın. Rapor, kısa bir cevap değil, çok sayfalı bir metin haline getiriyor.",
  "2. Ajusta el alcance": "2. Aralığı ayarlayın",
  "Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.": "Hedef uzunluğu ve maksimum bölüm sayısını seçin. Daha az bölüm daha derin metinler üretir; daha fazla bölüm, bir tane daha panoramik.",
  "3. Cobertura del corpus": "3. Corpus kapsamı",
  "Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.": "Nodus, indekslenmiş külliyatın tamamını gözden geçirir, bölümleri planlar ve kapsamın rehberliğinde yazar, her çalışmayı seçmenize gerek kalmadan alıntı yapar.",
  "4. Revisa y exporta": "4. İnceleyin ve dışa aktarın",
  "Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.": "Her kaynağı kontrol etmek için alıntıları açın, geri dönmek üzere raporu kaydedin ve hazır olduğunuzda Markdown veya PDF'ye aktarın.",
  "Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.": "Kapsama göre yönlendirilen ve alıntı yapılan tüm kaynaklarla birlikte çok sayfalı akademik rapor.",
