  "Aún no hay borradores guardados. Genera uno y guárdalo para volver a abrirlo o reutilizar su prompt más adelante.": "Henüz kaydedilmiş taslak yok. Bir tane oluşturun ve istemini daha sonra yeniden açmak veya yeniden kullanmak için kaydedin.",
