  "Bibliografía": "Kaynakça",
  "1. Delimita": "1. Sınırla",
  "Escribe el apartado que quieres construir: pregunta, capítulo, debate, hueco o marco teórico. Cuanto más concreto sea el objetivo, mejor se ordena la mesa.": "Oluşturmak istediğiniz bölümü yazın: soru, bölüm, tartışma, boşluk veya teorik çerçeve. Hedef ne kadar spesifik olursa tablo o kadar iyi organize edilir.",
  "2. Monta la mesa": "2. Masayı kurun",
  "Pulsa Preparar mesa y revisa ideas, temas, huecos, contradicciones, obras y rutas. Usa Todas las ideas cuando quieras una revisión amplia del corpus encontrado.": "Basın Tablo hazırlayın ve fikirleri, temaları, boşlukları, çelişkileri, çalışmaları ve rotaları gözden geçirin. Bulunan derlemin geniş bir incelemesini istediğinizde Tüm Fikirler'i kullanın.",
  "3. Decide el foco": "3. Odak noktasına karar verin",
  "Selecciona todo para explorar, vacía para empezar de cero o ajusta cada pestaña. La matriz final te dirá qué papel cumple cada material en el argumento.": "Keşfedilecek her şeyi seçin, sıfırdan başlamak için boş bırakın veya her sekmeyi ayarlayın. Son matris size her bir materyalin argümanda hangi rolü oynadığını söyleyecektir.",
  "4. Convierte en texto": "4. Metne dönüştürün",
  "Genera el borrador, abre las citas para verificar fuentes, guárdalo si quieres retomarlo y exporta Markdown cuando el hilo argumental ya tenga sentido para tu manuscrito.": "Taslağı oluşturun, kaynakları doğrulamak için alıntıları açın, geri dönmek istiyorsanız kaydedin ve hikaye akışı taslağınız için zaten anlamlı olduğunda Markdown'ı dışa aktarın.",
  "{n} evidencias": "{n} kanıt",
