  "Eliminar búsqueda guardada": "Kayıtlı aramayı sil",
  "La búsqueda por significado necesita embeddings. Configura el proveedor y la clave de embeddings en Ajustes e indexa la biblioteca.": "Anlam arayışı yerleştirmelere ihtiyaç duyar. Gömme sağlayıcısını ayarlayın ve Ayarlar'a girin ve kitaplığı dizine ekleyin.",
  "Salud del corpus": "Corpus Sağlığı",
