  "Todo en orden: no hay análisis, indexado ni recuperación pendientes.": "Her şey yolunda: bekleyen analiz, indeksleme veya kurtarma yok.",
  "Analiza a fondo {n} obra(s) prioritaria(s)": "{n} öncelikli çalışmayı iyice analiz edin",
  "Marcadas como leídas o seleccionadas, pero todavía sin ideas extraídas.": "Okundu veya seçildi olarak işaretlendi ancak hâlâ hiçbir fikir çıkarılmadı.",
  "Profundiza {n} obra(s) con solo análisis ligero": "{n} çalışmayı yalnızca ışık analiziyle derinleştirin",
  "Tienen temas pero aún no ideas; son las candidatas naturales al análisis profundo.": "Temaları var ama henüz fikirleri yok; Derin analiz için doğal adaylardır.",
  "Indexa {n} idea(s) sin embedding": "{n} fikri/fikirleri yerleştirmeden indeksler",
  "La búsqueda por significado, la fusión y los puentes dependen del índice semántico.": "Anlam arama, birleştirme ve köprü kurma anlamsal dizine bağlıdır.",
  "Indexa pasajes de {n} obra(s) con texto": "{n} eserden metin içeren pasajları indeksler",
  "Sin pasajes no hay búsqueda semántica de evidencia ni citas a nivel de fragmento.": "Pasajlar olmadan parça düzeyinde anlamsal kanıt veya alıntı araştırması yapılamaz.",
  "Recupera el texto de {n} obra(s)": "{n} eserin metnini kurtarır",
  "No se pudo extraer texto, pero hay vía de recuperación (re-escanear, OCR o descargar por DOI).": "Metin çıkarılamadı ancak bir kurtarma yolu var (yeniden tarama, OCR veya DOI ile indirme).",
  "Flujo guiado de tesis": "Rehberli Tez Akışı",
  "Flujo guiado de artículo": "Rehberli makale akışı",
  "Flujo guiado de manuscrito": "Rehberli el yazması akışı",
  "Proyecto listo para revisar, exportar o cerrar.": "Proje incelemeye, dışa aktarmaya veya kapatmaya hazır.",
  "Brief y pregunta": "Özetle ve sor",
  "Objetivo, alcance y criterio de lectura definidos.": "Tanımlanmış amaç, kapsam ve okuma kriterleri.",
  "Pregunta y cobertura": "Soru ve kapsam",
  "Pregunta principal conectada con la cobertura del corpus.": "Ana soru külliyat kapsamıyla bağlantılı.",
  "Corpus y materiales": "Derlem ve materyaller",
  "Obras, ideas, notas, huecos o borradores listos para integrarse.": "Bütünleştirilmeye hazır çalışmalar, fikirler, notlar, boşluklar veya taslaklar.",
  "Estructura argumental": "Arsa yapısı",
  "Debates, huecos y borradores organizados antes de intervenir el texto.": "Metne müdahale edilmeden önce düzenlenen tartışmalar, boşluklar ve taslaklar.",
  "Manuscrito": "El yazması",
  "Capítulo o artículo importado como texto editable y versionado.": "Düzenlenebilir ve sürümü değiştirilmiş metin olarak içe aktarılan bölüm veya makale.",
  "Revisión y salida": "İnceleme ve ayrılış",
  "Relaciones, sugerencias verificables y exportación final.": "İlişkiler, doğrulanabilir öneriler ve nihai ihracat.",
  "Editar brief": "Özeti düzenle",
  "Marcar cobertura": "Kapsamı işaretle",
