  "Preparar estructura": "Yapıyı hazırlayın",
  "Subir capítulo": "Bölüm yükle",
  "Revisar capítulo": "Bölümü gözden geçir",
  "Completado": "Tamamlandı",
  "Objetivo, alcance, pregunta principal y criterio de selección": "Amaç, kapsam, ana soru ve seçim kriterleri",
  "Guardar brief": "Özeti kaydet",
  "Brief actualizado. El flujo guiado ya usa este objetivo.": "Özet güncellendi. Kılavuzlu akış zaten bu hedefi kullanıyor.",
  "Cobertura marcada como en curso.": "Kapsam devam ediyor olarak işaretlendi.",
  "Materiales preparados para el estado de la cuestión.": "Son teknolojiye uygun olarak hazırlanmış malzemeler.",
  "Estructura argumental preparada.": "Hazırlanan arsa yapısı.",
  "No se encontraron nuevas sugerencias verificables para este capítulo.": "Bu bölüm için doğrulanabilir yeni öneri bulunamadı.",
  "Define el objetivo, el alcance, la pregunta principal y el criterio de selección de fuentes. Este texto aparece en la cabecera del proyecto, se envía como contexto a la IA al generar sugerencias y se incluye en la exportación.": "Amacı, kapsamı, ana soruyu ve kaynak seçim kriterlerini tanımlar. Bu metin proje başlığında görünür, öneriler oluşturulurken bağlam olarak yapay zekaya gönderilir ve dışa aktarmaya dahil edilir.",
  "Vincula tu pregunta de investigación con el corpus: indica qué áreas ya están cubiertas y qué falta por explorar. Marcar este paso como en curso activa la sección de cobertura en el proyecto.": "Araştırma sorunuzu derlemle ilişkilendirin: hangi alanların halihazırda kapsandığını ve neyin keşfedilmeyi kaldığını belirtin. Bu adımın devam ediyor olarak işaretlenmesi projedeki kapsam bölümünü etkinleştirir.",
  "Añade obras, ideas, notas, huecos, debates y borradores al proyecto. Estos materiales son los que la IA usará para proponer inserciones con citas verificables en el manuscrito.": "Projeye çalışmalar, fikirler, notlar, boşluklar, tartışmalar ve taslaklar ekleyin. Bu materyaller, yapay zekanın yazıya doğrulanabilir alıntılarla eklemeler önermek için kullanacağı materyallerdir.",
  "Organiza los debates, huecos y borradores que estructurarán el argumento antes de redactar los capítulos. Puedes activar cada bloque por separado para marcar que está listo para usarse.": "Bölümleri yazmadan önce argümanı yapılandıracak tartışmaları, boşlukları ve taslakları düzenleyin. Her bloğu ayrı ayrı etkinleştirerek kullanıma hazır olarak işaretleyebilirsiniz.",
  "Importa un capítulo o artículo como texto editable. Nodus lo versiona automáticamente y permite aplicar sugerencias sobre el borrador.": "Bir bölümü veya makaleyi düzenlenebilir metin olarak içe aktarın. Nodus bunu otomatik olarak sürümlendirir ve taslak üzerinde önerileri uygulamanıza olanak tanır.",
  "Genera sugerencias verificables contra el corpus y revisa las citas del manuscrito antes de exportar o cerrar el proyecto.": "Projeyi dışa aktarmadan veya kapatmadan önce derlemin doğrulanabilir önerilerini oluşturun ve taslak alıntıları gözden geçirin.",
  "Guardando brief...": "Özet kaydediliyor...",
