  "Sube un capítulo o artículo para convertirlo en texto editable. Se guardará como nota vinculada y versionada.": "Düzenlenebilir metne dönüştürmek için bir bölüm veya makale yükleyin. Bağlantılı ve versiyonlu bir not olarak kaydedilecektir.",
  "Genera sugerencias de inserción con citas verificables y revisa las citas del capítulo antes de exportar.": "Doğrulanabilir alıntılarla ekleme önerileri oluşturun ve dışa aktarmadan önce bölüm alıntılarını gözden geçirin.",
  "Sección actualizada. El flujo guiado refleja el cambio.": "Güncellenen bölüm. Yönlendirilmiş akış değişimi yansıtır.",
