  "{n} ideas del capítulo": "{n} bölüm fikirleri",
  "Extrae las ideas de este capítulo (no se añaden al grafo) y busca cómo se relacionan con tu biblioteca: ideas, notas, pasajes y obras.": "Bu bölümdeki fikirleri çıkarın (grafiğe eklenmezler) ve kitaplığınızla nasıl ilişkili olduklarını bulun: fikirler, notlar, pasajlar ve çalışmalar.",
  "Analiza las relaciones para ver cómo conecta este capítulo con toda tu biblioteca.": "Bu bölümün tüm kitaplığınıza nasıl bağlandığını görmek için ilişkileri analiz edin.",
  "Sin relaciones encontradas en la biblioteca.": "Kitaplıkta ilişki bulunamadı.",
  "La búsqueda de relaciones necesita un proveedor de embeddings configurado en Ajustes.": "İlişki arama, Ayarlar'da yapılandırılmış bir yerleştirme sağlayıcısı gerektirir.",
  "No se pudieron extraer ideas de este capítulo.": "Bu bölümden hiçbir fikir çıkarılamadı.",
