  "Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.": "Öğrenme bilimi üzerine altı çalışmadan oluşan bir demo külliyatı yükleyin. Zotero'yu bağlamadan veya bir AI anahtarı yapılandırmadan grafikte, fikirlerde, tartışmalarda, boşluklarda ve notlarda gezinebileceksiniz.",
  "Cargar demo": "Demoyu yükle",
  "Explora con datos de ejemplo": "Örnek verilerle keşfedin",
  "Prueba sin configurar nada": "Hiçbir şey yapılandırmadan deneyin",
  "Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.": "Fikirlerden, kanıtlardan, temalardan ve özetlerden bağımsız rehberlik özetleri oluşturun. Bunlar alıntı yapılabilecek deliller değildir.",
  "El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.": "Derin analizde tam metin değil, yalnızca özet kullanıldı (analiz sırasında PDF/EPUB mevcut değildi). Zotero'dayken yeniden tarayın.",
  "El texto o el modelo de embeddings cambió.": "Metin veya yerleştirme deseni değişti.",
  "Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.": "Fikirler metnin önceki sürümüne ait. Güncel metni kullanmak için yeniden analiz edin.",
  "El texto cambió; vuelve a indexar sus fragmentos.": "Metin değişti; pasajlarını yeniden dizine ekleyin.",
  "Los fragmentos se indexaron con otro modelo de embeddings.": "Pasajlar farklı bir gömme modeliyle dizine eklendi.",
  "El texto y el modelo de embeddings cambiaron.": "Hem metin hem de gömme modeli değişti.",
  "Algunos fragmentos no tienen un embedding válido.": "Bazı pasajların geçerli bir gömmesi yok.",
  "Generar resúmenes faltantes": "Eksik özetler oluştur",
  "Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.": "Eksik veya eski eserlerdeki tam metin parçalarını indeksler. Fikirlerin analizini gerektirmez; metin alıntı yapılabilir kanıt olarak kalır.",
  "Indexar pasajes": "Dizin pasajları",
  "Indexar pasajes de esta obra": "Bu çalışmadan indeks pasajları",
  "Indexar todo": "Tümünü indeksle",
  "No hay obras «solo abstract» para reanalizar.": "Yeniden analiz edilecek “yalnızca soyut” çalışmalar yoktur.",
  "obsoleto": "modası geçmiş",
  "Pasajes (texto completo)": "Pasajlar (tam metin)",
  "Procesar faltantes": "İşlem eksik",
  "Procesar pasajes faltantes": "Eksik pasajları işleyin",
  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "\"Yalnızca özet\" olan {n} çalışma(lar) için sıraya alınan yeniden analiz. Sıradaki ilerlemeyi göreceksiniz.",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "Yalnızca özet ile analiz edilen çalışmaları yeniden analiz edin (bunlar analiz edilirken PDF/EPUB mevcut değildi). Metni zaten Zotero'da bulunduranlar, analizi tam olarak elde edeceklerdir; geri kalanı ücretsiz olarak göz ardı edilir. Devam etmek?",
  "Reanalizar": "Yeniden analiz et",
  "Reanalizar «solo abstract»": "“Yalnızca özet”i yeniden ayrıştır",
  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "Kütüphanenin tamamında döngü yapar ve yalnızca değişen dizinleri günceller. Mevcut olanlar atlanmıştır.",
  "resumen": "özet",
  "solo abstract": "sadece soyut",
  "Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.": "PDF/EPUB mevcut olmadığından derinlemesine analizde yalnızca özetin kullanıldığı çalışmaları yeniden analiz edin. Halihazırda metne sahip olanlar tüm analizi elde edebilir; geri kalanı ücretsiz olarak göz ardı edilir.",
  "Añade citas textuales con su página o rango de páginas.": "Sayfanıza veya sayfa aralığınıza metin içi alıntılar ekleyin.",
  "Añadir cita": "Randevu ekle",
