  "Estás viendo un corpus de ejemplo. Sal del modo demo para empezar con tu propia biblioteca.": "Örnek bir derlem görüntülüyorsunuz. Kendi kitaplığınızı kullanmaya başlamak için demo modundan çıkın.",
