  "Eliminar recorrido guardado": "Kaydedilen turu sil",
  "Cómo se organiza": "Nasıl organize ediliyor",
  "Genera una tesis central y puntos clave a partir de todas las ideas extraídas de esta obra.": "Bu çalışmadan çıkarılan tüm fikirlerden merkezi bir tez ve kilit noktalar oluşturun.",
  "Síntesis de la obra": "İşin sentezi",
