  "Proyecto completo": "Projeyi tamamla",
  "Seccion del proyecto": "Proje bölümü",
  "texto completo": "tam metin",
  "Reinicializar el grafo": "Grafiği sıfırla",
  "Reinicializar el grafo borrará TODAS las ideas, temas, conexiones, autores y huecos, y dejará cada obra sin analizar. Tu biblioteca de Zotero y tus ajustes se conservan. Esta acción no se puede deshacer.": "Grafiğin sıfırlanması TÜM fikirleri, temaları, bağlantıları, yazarları ve boşlukları silecek ve her çalışmayı analiz edilmeden bırakacaktır. Zotero kitaplığınız ve ayarlarınız korunur. Bu eylem geri alınamaz.",
  "Eliminar borrador": "Taslağı sil",
  "Eliminar informe": "Raporu sil",
  "Procesar toda la biblioteca": "Kitaplığın tamamını işle",
  "Escribir": "Yaz",
  "General": "Genel",
  "Paleta de comandos": "Komut Paleti",
  "Comandos": "Komutlar",
  "Plegar grupo": "Grubu katla",
  "Mostrar grupo": "Grubu göster",
  "Ir a una sección o ejecutar una acción…": "Bir bölüme gidin veya bir eylemi gerçekleştirin…",
  "Actualizar (sincronizar Zotero)": "Güncelleme (Zotero'yu senkronize et)",
  "Algo ha fallado en esta sección": "Bu bölümde bir şeyler ters gitti",
  "Se produjo un error inesperado al mostrar esta vista. El resto de la app sigue funcionando: reinténtalo o cambia de sección.": "Bu görünüm görüntülenirken beklenmeyen bir hata oluştu. Uygulamanın geri kalanı çalışmaya devam ediyor: tekrar deneyin veya bölümleri değiştirin.",
  "Recargar Nodus": "Nodus'u yeniden şarj edin",
  "Inmersión": "Dalış",
  "Domina un tema de tu corpus en una tarde.": "Bir öğleden sonra külliyatınızdan bir konuya hakim olun.",
  "Una ruta completamente guiada: panorama, estaciones con citas literales del texto completo, contrastes entre autores, fronteras del corpus y examen final. Todo queda grabado para retomarlo cuando quieras.": "Tamamen yönlendirilmiş bir rota: genel bakış, tam metinden birebir alıntılar içeren istasyonlar, yazarlar arasındaki zıtlıklar, derlem sınırları ve final sınavı. İstediğiniz zaman geri dönebilmeniz için her şey kaydedilir.",
  "¿De qué quieres hacerte experto? P. ej.: uso franquista de las fiestas y tradiciones": "Hangi konuda uzman olmak istiyorsunuz? Örneğin: Franco'nun festival ve gelenekleri kullanması",
  "Exprés": "Ekspres",
  "Una tarde": "bir öğleden sonra",
  "Profunda": "Derin",
  "~6 paradas": "~6 durak",
  "~12 paradas": "~12 durak",
  "~20 paradas": "~20 durak",
  "Cartografiando…": "Haritalama…",
  "Explorar el territorio": "Bölgeyi keşfedin",
  "Las preguntas siempre se pueden saltar durante la sesión": "Oturum sırasında sorular her zaman atlanabilir",
  "Tus inmersiones": "Dalışlarınız",
  "Aún no hay inmersiones guardadas. Cada recorrido que generes quedará aquí, con su progreso y tus respuestas, listo para retomarlo.": "Henüz kayıtlı dalış yok. Oluşturduğunuz her rota, ilerlemesi ve yanıtlarınızla birlikte ona geri dönmeye hazır olarak burada kalacaktır.",
  "{n} estaciones": "{n} istasyon",
  "Eliminar inmersión": "Dalışı sil",
  "¿Eliminar esta inmersión y todo su progreso? Esta acción no se puede deshacer.": "Bu dalış ve tüm ilerlemesi silinsin mi? Bu eylem geri alınamaz.",
  "Esto es lo que tu corpus sabe del tema. Sin IA todavía: solo embeddings y grafo.": "Bu, korpusunuzun konu hakkında bildiği şeydir. Henüz yapay zeka yok: yalnızca yerleştirmeler ve grafikler.",
  "No hay material suficiente para una inmersión": "Dalış için yeterli malzeme yok",
  "Generando inmersión…": "Dalış oluşturuluyor…",
  "Comenzar inmersión": "Dalışı başlat",
  "obras": "çalışır",
  "autores": "yazarlar",
  "debates": "tartışmalar",
  "Ruta de ~{n} estaciones guiadas: panorama, contrastes, fronteras y examen final{quiz}. La IA ajusta el número según lo que el tema pida.": "~{n} rehberli istasyonların rotası: panorama, kontrastlar, sınırlar ve final sınavı{quiz}. Yapay zeka, temanın istediği şeye göre sayıyı ayarlar.",
  "(sin preguntas)": "(soru yok)",
  "Voces principales": "Kurşun vokal",
  "{n} ideas relevantes": "{n} alakalı fikirler",
  "Temas que toca": "İşlenen konular",
  "Ideas más fuertes": "Daha güçlü fikirler",
  "No hay suficientes ideas conectadas para dibujar el territorio.": "Bölgeyi çizmeye yetecek kadar bağlantılı fikir yok.",
  "Generando tu inmersión…": "Dalışınız oluşturuluyor…",
  "Cada respuesta de la IA se guarda: este recorrido será tuyo para siempre y podrás retomarlo sin regenerar nada.": "Her AI yanıtı kaydedilir: Bu tur sonsuza kadar sizin olacaktır ve hiçbir şeyi yeniden oluşturmadan bu tura geri dönebilirsiniz.",
  "Cada parte generada por la IA se guarda: podrás retomar el recorrido sin regenerarlo. Las respuestas de test y texto se limpian al reiniciar.": "Yapay zeka tarafından oluşturulan her parça kaydedilir: rotayı yeniden oluşturmadan devam edebileceksiniz. Yeniden başlatmanın ardından test ve metin yanıtları silinir.",
  "Puedes cambiar de sección: la generación seguirá en segundo plano y este progreso reaparecerá cuando vuelvas.": "Bölümleri değiştirebilirsiniz: nesil arka planda devam edecek ve geri döndüğünüzde bu ilerleme yeniden ortaya çıkacaktır.",
  "No se pudo generar la inmersión.": "Dalış oluşturulamadı.",
  "Cartografiando el territorio": "Bölgenin haritalanması",
  "Diseñando la ruta": "Rotayı tasarlama",
  "Redactando el panorama": "Panoramanın yazılması",
