  "Estación {n}": "İstasyon {n}",
  "Contrastes": "Kontrastlar",
  "Fronteras": "Kenarlıklar",
  "El mapa mental antes de bajar al detalle: posiciones, autores y cómo se conecta la ruta.": "Detaylara inmeden önce zihinsel harita: konumlar, yazarlar ve rotanın nasıl bağlantılı olduğu.",
  "Vocabulario del campo": "Alan sözlüğü",
  "La ruta: {n} estaciones → contrastes entre autores → fronteras del corpus → examen final.": "Rota: {n} istasyonlar → yazarlar arasındaki zıtlıklar → derlem sınırları → final sınavı.",
  "Citas que un experto conoce de memoria": "Bir uzmanın ezbere bildiği alıntılar",
  "Quién sostiene qué": "Kim neyi tutuyor",
  "Ver idea de origen": "Kaynak fikrine bakın",
  "Este rincón del grafo · {n} ideas": "Grafiğin bu köşesi · {n} fikir",
  "Comprueba que lo dominas": "Bu konuda uzmanlaşıp uzmanlaşmadığınızı kontrol edin",
  "opcional, puedes saltarlo": "isteğe bağlı, atlayabilirsiniz",
  "Ver menos": "daha az gör",
  "Leer el pasaje completo": "Pasajın tamamını okuyun",
  "p. {p}": "s. {p}",
  "Quién dice qué, frente a frente": "Kim ne diyor yüz yüze",
  "La matriz que distingue a un experto: cada autor frente a cada sub-pregunta. Las celdas vacías también informan — ese autor no se pronuncia ahí.": "Bir uzmanı ayıran matris: her yazar her alt soruyla karşı karşıyadır. Boş hücreler aynı zamanda yazarın orada konuşmadığını da bildirir.",
  "No hay suficientes autores con posiciones diferenciadas en este tema.": "Bu konuda farklı konumlara sahip yeterli sayıda yazar yok.",
  "Sub-pregunta": "Alt soru",
  "Lo que tu corpus no sabe (todavía)": "Korpusunuzun bilmediği şey (henüz)",
  "Conocer los límites es parte de la maestría: aquí terminan tus fuentes y empieza el trabajo futuro.": "Sınırları bilmek ustalığın bir parçasıdır: Kaynaklarınız burada biter ve gelecekteki çalışmalar başlar.",
  "No se detectaron huecos relevantes para este tema. Buen síntoma.": "Bu konuyla ilgili herhangi bir boşluk tespit edilmedi. İyiye işaret.",
  "Inmersión completada": "Dalış tamamlandı",
  "Demuestra que eres experto": "Uzman olduğunuzu gösterin",
  "Cubre todas las estaciones. Cada pregunta es opcional: respóndelas para medirte o sáltalas sin más.": "Tüm istasyonları kapsar. Her soru isteğe bağlıdır: kendinizi ölçmek için soruları yanıtlayın veya doğrudan atlayın.",
  "Sesión sin preguntas: cierra con la explicación final y da la inmersión por completada.": "Sorusuz oturum: son açıklamayla kapanır ve dalış tamamlanmış sayılır.",
  "Dominio del corpus verificado": "Doğrulanmış korpus alanı",
  "{s} estaciones · {q} preguntas respondidas{score}": "{s} istasyon · {q} soru yanıtlandı{score}",
  "nota media": "ortalama not",
  "Guardar dossier en notas": "Dosyayı notlara kaydet",
  "Volver al inicio": "Başa dön",
  "El cierre Feynman": "Feynman'ın Kapanışı",
  "Hazlo en voz alta o por escrito. Si te atascas en un punto, vuelve a su estación — para eso están las flechas.": "Bunu yüksek sesle veya yazılı olarak yapın. Bir noktada takılıp kalırsanız istasyonunuza geri dönün; oklar bunun içindir.",
