  "La lección": "ders",
  "Lectura guiada: citas que un experto conoce de memoria": "Rehberli okuma: bir uzmanın ezbere bildiği alıntılar",
  "Cómo leer este pasaje": "Bu pasaj nasıl okunmalı?",
