  "preguntas": "sorular",
  "El territorio completo": "Tüm bölge",
  "Falta la clave del proveedor de IA: configúrala en Ajustes": "AI Sağlayıcı Anahtarı Eksik: Ayarlar'da ayarlayın",
  "Profundiza: informe Deep Research del tema": "Daha derine inin: Konuyla ilgili Derin Araştırma raporu",
  "Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.": "Artık konuya hakim olduğunuza göre, tüm kaynakların alıntılandığı çok sayfalı bir akademik rapor oluşturun. Deep Research'e kaydedilir ve onu dışa aktarabilir veya yazınızda alıntı yapabilirsiniz.",
  "Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.": "Bölümleri değiştirebilirsiniz: rapor oluşturulmaya devam edecek ve geri döndüğünüzde ilerlemeyi gösterecektir.",
  "Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.": "Kaydedilen dosya: «{t}» · {s} bölüm · ~{p} sayfa. Bunu Derin Araştırma → kayıtlı raporlarda bulabilirsiniz.",
  "Generar de nuevo": "Tekrar oluştur",
  "Seleccionar modelo": "Modeli seçin",
  "Usar modelo de síntesis": "Sentez modelini kullan",
  "Modelo inicial para las tareas de IA ({n} disponibles)": "Yapay zeka görevleri için başlangıç modeli ({n} mevcut)",
  "Modelos favoritos para los selectores independientes": "Bağımsız seçicilerin favori modelleri",
  "Los modelos de análisis se configuran en Ajustes.": "Analiz modelleri Ayarlar'da yapılandırılır.",
  "Modelos de análisis: Ajustes": "Analiz modelleri: Ayarlar",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con los modelos configurados en Ajustes, sin volver a leer los documentos ni re-extraer ideas.": "Halihazırda çıkarılan fikirleri (ifadeler, bulgular...) alır ve belgeleri yeniden okumaya veya fikirleri yeniden çıkarmaya gerek kalmadan Ayarlar'da yapılandırılan modellerle bu temalar altında yeniden gruplandırır.",
  "Cada tarea usa su propio modelo. Los escaneos, resúmenes, fusión y embeddings obedecen estos ajustes; Chat, Deep Research, Inmersión y las demás herramientas conservan el modelo elegido dentro de su propia sección.": "Her görev kendi modelini kullanır. Taramalar, özetler, birleştirme ve yerleştirmeler bu ayarlara uyar; Chat, Deep Research, Immersion ve diğer araçlar seçilen modeli kendi bölümlerinde tutar.",
  "Modelo de síntesis general (fallback inicial para herramientas con selector propio)": "Genel sentez modeli (kendi seçicileri olan araçlar için ilk geri dönüş)",
  "modelos por tarea": "göreve göre modeller",
  "Extracción: {provider}": "Çıkarma: {provider}",
  "Síntesis: {provider}": "Sentez: {provider}",
  "Configura los modelos de IA": "Yapay zeka modellerini yapılandırma",
  "La sincronización puede funcionar, pero Nodus necesita modelos separados de extracción y síntesis para analizar el corpus.": "Senkronizasyon işe yarayabilir ancak Nodus'un derlemi analiz etmek için ayrı çıkarma ve sentez modellerine ihtiyacı vardır.",
  "Generación de imágenes": "Görüntü oluşturma",
  "Configuración independiente para las imágenes decorativas opcionales. OpenAI usa su API oficial de imágenes y reutiliza la clave de OpenAI; Google reutiliza la clave de Gemini.": "İsteğe bağlı dekoratif görüntüler için ayrı konfigürasyon. OpenAI, resmi Görüntü API'sini kullanır ve OpenAI anahtarını yeniden kullanır; Google, Gemini anahtarını yeniden kullanır.",
  "Actualizar modelos": "Modelleri güncelle",
  "Estilo predeterminado": "Varsayılan stil",
  "Selección actual": "Mevcut seçim",
  "Buscar por proveedor, nombre o identificador…": "Tedarikçiye, isme veya tanımlayıcıya göre arayın…",
  "Proveedor y nombre": "Tedarikçi ve isim",
  "Orden alfabético": "alfabetik sıra",
  "Precio por imagen: menor a mayor (por proveedor)": "Resim başına fiyat: düşükten yükseğe (sağlayıcıya göre)",
  "Precio por imagen: mayor a menor (por proveedor)": "Resim başına fiyat: yüksekten düşüğe (sağlayıcıya göre)",
  "Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.": "Satıcılar farklı boyut ve metrikler yayınladığından, fiyata göre sıralama her satıcı içinde ayrı ayrı uygulanır. Direkt fiyatı olmayan modeller ise sonuncu; herhangi bir maliyet tahmin edilmemektedir.",
  "Consultando catálogos oficiales…": "Resmi kataloglara başvuruluyor…",
