  "Se realizará una nueva generación y puede producir un coste adicional. ¿Continuar?": "Yeni nesil yapılacak ve ek maliyete neden olabilir. Devam etmek?",
  "Eliminar imagen": "Resmi sil",
  "La imagen se eliminará del almacenamiento local. El contenido principal no cambiará.": "Resim yerel depolama alanından silinecek. Ana içerik değişmeyecek.",
  "Generar inmersión": "Dalış oluştur",
