  "Puedes empezar ya: la imagen nunca bloquea el contenido.": "Şimdi başlayabilirsiniz: görüntü hiçbir zaman içeriği engellemez.",
  "Diseño": "Tasarım",
  "Diseño de la imagen": "Görüntü tasarımı",
  "Ajusta el estilo y la escena. Se genera una imagen nueva.": "Stili ve sahneyi ayarlayın. Yeni bir görüntü oluşturulur.",
  "Descripción de la escena": "Sahne açıklaması",
  "Describe la escena que quieres ver. Si lo dejas vacío, se deduce del contenido.": "Görmek istediğiniz sahneyi anlatın. Boş bırakmanız durumunda içerikten düşülür.",
  "El estilo y las protecciones de «sin texto» se aplican automáticamente al generar.": "Oluşturma sırasında \"metin yok\" stili ve korumalar otomatik olarak uygulanır.",
  "La imagen aparecerá aquí una vez generada.": "Resim oluşturulduktan sonra burada görünecektir.",
  "Añadir imagen decorativa": "Dekoratif resim ekle",
  "La imagen no pudo generarse.": "Resim oluşturulamadı.",
  "Al generar se solicita una imagen nueva, que puede tener un coste adicional.": "Oluşturma sırasında ek maliyete neden olabilecek yeni bir görüntü istenir.",
  "Subir mi imagen": "Resmimi yükle",
  "Volver a la imagen anterior": "Önceki resme dön",
  "Tu imagen se comprime automáticamente para no sobrecargar el almacenamiento.": "Depolama alanını aşırı yüklememek için görseliniz otomatik olarak sıkıştırılır.",
  "No se pudo leer el archivo de imagen.": "Resim dosyası okunamadı.",
