  "(local)": "(yerel)",
  "Cargado en memoria": "Belleğe yüklendi",
  "Ollama debe estar en marcha y los modelos descargados con \"ollama pull\". No requiere clave.": "Ollama çalışıyor olmalı ve modeller \"ollama pull\" ile indirilmelidir. Şifre gerekmez.",
  "Activa el servidor local en LM Studio (Developer → Start Server) y carga al menos un modelo. No requiere clave.": "LM Studio'da yerel sunucuyu etkinleştirin (Geliştirici → Sunucuyu Başlat) ve en az bir model yükleyin. Şifre gerekmez.",
  "Dirección del servidor (IP y puerto)": "Sunucu adresi (IP ve bağlantı noktası)",
  "Probando…": "Test ediliyor…",
  "Probar conexión": "Bağlantıyı test edin",
  "Conectado{version} · {n} modelos disponibles": "Bağlı{version} · {n} model mevcut",
  "Sin conexión: {msg}": "Çevrimdışı: {msg}",
  "•••••••• token guardado (opcional)": "•••••••• kayıtlı jeton (isteğe bağlı)",
  "token de acceso (opcional)": "erişim belirteci (isteğe bağlı)",
  "El servidor no reporta modelos. Descarga o carga uno primero.": "Sunucu modelleri raporlamaz. Önce bir tane indirin veya yükleyin.",
  "Proveedor local: no necesita clave. Usa la dirección por defecto; puedes cambiar IP y puerto en Ajustes → Proveedores.": "Yerel sağlayıcı: anahtara gerek yok. Varsayılan adresi kullanın; IP'yi ve bağlantı noktasını Ayarlar → Sağlayıcılar bölümünde değiştirebilirsiniz.",
  "Traducciones": "Çeviriler",
  "Traducciones con IA": "Yapay Zeka ile Çeviriler",
  "Traduce este contenido a otro idioma. Cada idioma se guarda y puede regenerarse o eliminarse.": "Bu içeriği başka bir dile çevirin. Her dil kaydedilir ve yeniden oluşturulabilir veya silinebilir.",
  "Generar traducción": "Çeviri oluştur",
  "Traduciendo…": "Çeviriliyor…",
  "Genera la traducción con el modelo de IA configurado": "Çeviriyi yapılandırılmış yapay zeka modeliyle oluşturun",
  "La traducción de un texto largo puede tardar. Puedes cerrar esta ventana: se guardará y aparecerá aquí al volver.": "Uzun bir metnin çevirisi zaman alabilir. Bu pencereyi kapatabilirsiniz: Kaydedilecek ve geri döndüğünüzde burada görünecektir.",
  "Cargando traducciones…": "Çeviriler yükleniyor…",
  "Aún no hay traducciones. Elige un idioma y genera la primera.": "Henüz çeviri yok. Bir dil seçin ve ilkini oluşturun.",
  "Regenerar esta traducción": "Bu çeviriyi yeniden oluştur",
  "Eliminar traducción": "Çeviriyi sil",
  "¿Eliminar la traducción a {lang}? Esta acción no se puede deshacer.": "{lang} diline yapılan çeviri kaldırılsın mı? Bu eylem geri alınamaz.",
  "Seleccionar todo": "Tümünü seç",
  "Deseleccionar todo": "Tümünün seçimini kaldır",
  "Eliminar seleccionados": "Seçileni sil",
  "Eliminar seleccionadas": "Seçileni sil",
  "Eliminar informes": "Raporları sil",
  "¿Eliminar {n} informes guardados? Esta acción no se puede deshacer.": "{n} kayıtlı rapor silinsin mi? Bu eylem geri alınamaz.",
  "{n} informes eliminados.": "{n} raporlar kaldırıldı.",
  "Eliminar inmersiones": "Dalışları sil",
  "¿Eliminar {n} inmersiones y todo su progreso? Esta acción no se puede deshacer.": "{n} dalış ve bunların tüm ilerlemeleri silinsin mi? Bu eylem geri alınamaz.",
  "Nueva inmersión": "Yeni dalış",
  "Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.": "Derleminizden bir konu üzerinde uzmanlaşın: panorama, birebir alıntılarla sezonlar, kontrastlar, sınırlar ve final sınavı. Her şey devam ettirilmek üzere kaydedilir.",
  "Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.": "Derleminizdeki bir konuya hakim olun: içerik ve ilerleme geri dönüş için kaydedilir; Cevaplarınız yeniden başlatıldığında silinir.",
  "Buscar entre tus inmersiones…": "Dalışlarınız arasında arama yapın…",
  "Cargando inmersiones…": "Dalışlar yükleniyor…",
  "Ninguna inmersión coincide con tu búsqueda.": "Aramanızla eşleşen dalış yok.",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.": "Henüz dalış yok. İlkini yaratın ve o, ilerlemeniz ve cevaplarınızla birlikte ona geri dönmeye hazır olarak burada olacaktır.",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.": "Henüz dalış yok. İlkini yaratın ve ilerlemesiyle birlikte burada, devam etmeye hazır olacak.",
  "Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.": "Yeniden başlat, önceki yanıtları siler ve turu baştan başlatır.",
  "Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).": "Konuyu ve kapsamı seçin. Oluşturmadan önce korpusunuzun ne bildiğini göreceksiniz (AI olmadan).",
  "Duración": "Süre",
  "Novedades": "Haberler",
  "Esto es lo nuevo en esta versión de Nodus.": "Nodus'un bu sürümündeki yenilikler bunlar.",
  "¡Entendido!": "Anladım!",
  "Plegar": "Katla",
  "Desplegar": "Dağıt",
  "Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "İzlenecek koleksiyonları seçin. Bir koleksiyonun çok büyük olması durumunda belirli alt koleksiyonları seçmek için herhangi bir koleksiyonu genişletin. Meta veriler dahil edilmiştir; Ayarlar'da otomasyonu etkinleştirmediğiniz sürece analizler manuel olarak başlatılır.",
  "Fuentes primarias": "Birincil kaynaklar",
  "Genealogía": "Soy araştırması",
  "Bases de datos": "Veritabanları",
  "próximamente": "yakında",
  "Tipo de bóveda: {type}.": "Kasa türü: {type}.",
  "Mi bóveda": "Kasam",
  "TU PRIMERA BÓVEDA": "İLK KASANIZ",
  "Vamos a crear tu primera bóveda": "İlk kasanızı oluşturalım",
  "Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.": "Ona bir ad verin ve modunu seçin. Mod, hangi bölümleri göreceğinizi ve yapay zekânın sizinle nasıl çalışacağını belirler; istediğiniz zaman başka modlarda yeni kasalar oluşturabilirsiniz.",
  "Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.": "Ardından sihirbaz, yapay zekâ modelini ve embedding modelini seçmenize yardımcı olur. Adı istediğiniz zaman kasa seçicisinden değiştirebilirsiniz.",
  "Crear mi bóveda": "Kasamı oluştur",
  "Nombre de la bóveda": "Kasa adı",
  "Tipo de bóveda": "Kasa türü",
  "Personas": "İnsanlar",
  "Buscar por nombre o variante…": "İsme veya varyanta göre arayın…",
  "Añadir persona": "Kişi ekle",
  "Importar un árbol GEDCOM (Gramps, Ancestry…)": "Bir GEDCOM ağacını içe aktarın (Gramps, Ancestry…)",
  "Importar": "İthalat",
  "Exportar a GEDCOM para Gramps / Ancestry": "Gramps/Ancetry için GEDCOM'a aktar",
  "Buscar registros que podrían ser la misma persona": "Aynı kişi olabilecek kayıtları bulun",
  "Revisar coincidencias": "Eşleşmeleri inceleyin",
  "Revisar parentescos propuestos a partir de la evidencia": "Kanıta dayalı olarak önerilen ilişkileri gözden geçirin",
  "Parentescos sugeridos": "Önerilen İlişkiler",
  "Aún no hay personas. Se crean al analizar fuentes primarias o añadiéndolas a mano.": "Henüz kimse yok. Birincil kaynakları analiz ederek veya elle ekleyerek oluşturulurlar.",
