  "Reemplazar el archivo adjunto": "Eki değiştirin",
  "Se sustituirá el archivo de «{title}» por otro y se volverá a extraer su texto. Se conservan el título, la clasificación, las etiquetas y las personas vinculadas. ¿Continuar?": "“{title}” dosyası başka bir dosyayla değiştirilecek ve metni tekrar çıkarılacaktır. Başlık, derecelendirme, etiketler ve bağlantılı kişiler korunur. Devam etmek?",
