  "Extraer personas y eventos": "Kişileri ve olayları çıkarın",
  "Sustituir el archivo adjunto por otro (se vuelve a extraer su texto)": "Ekli dosyayı başka bir dosyayla değiştirin (metni yeniden çıkarılır)",
