  "¿Eliminar este adjunto? Esta acción no se puede deshacer.": "Bu ek silinsin mi? Bu eylem geri alınamaz.",
  "Resume el contenido de esta fila en una o dos frases claras.": "Bu satırın içeriğini bir veya iki net cümleyle özetleyin.",
  "Clasifica esta fila en una categoría breve (una o dos palabras). Devuelve solo la categoría.": "Bu satırı kısa bir kategoriye (bir veya iki kelime) sınıflandırın. Yalnızca kategoriyi döndürür.",
  "Extrae de 3 a 5 palabras clave separadas por comas. Devuelve solo las palabras clave.": "Virgülle ayırarak 3 ila 5 anahtar kelimeyi çıkarın. Yalnızca anahtar kelimeleri döndürür.",
  "Indica el sentimiento del contenido: positivo, negativo o neutro. Devuelve solo una palabra.": "İçeriğin duygusunu belirtir: olumlu, olumsuz veya tarafsız. Yalnızca bir sözcük döndürür.",
  "Traduce el contenido principal de esta fila al inglés. Devuelve solo la traducción.": "Bu satırın ana içeriğini İngilizceye çevirin. Yalnızca çeviriyi döndürür.",
  "Describe en 40-60 palabras la imagen adjunta a esta fila.": "Bu satıra eklenen görseli 40-60 kelimeyle tanımlayın.",
  "Transcribe literalmente todo el texto que aparezca en la imagen o archivo adjunto. Devuelve solo la transcripción.": "Resimde veya ekli dosyada görünen tüm metni tam anlamıyla yazıya dökün. Yalnızca transkripti döndürür.",
