  "Demo de bases de datos": "Veritabanı Demosu",
  "Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.": "Tüm sütun türlerini, ilişkileri, kayıtları, analizleri, konuşmayı ve örnek notları içeren üç araştırma tablosu. Rehberli bir eğitim içerir.",
  "Cargar demo de bases de datos": "Veritabanı demosunu yükle",
  "Cargar datos de ejemplo": "Örnek verileri yükle",
  "Tutorial de bases de datos": "Veritabanı Eğitimi",
  "La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.": "Veritabanı listesi, yazılan sütunları içeren tablo, hücre düzenleme, analiz ve sohbet bölümleri.",
  "Se mostrará el tutorial de bases de datos.": "Veritabanı eğitimi görüntülenecektir.",
  "Bienvenido al modo bases de datos": "Veritabanı moduna hoş geldiniz",
  "Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.": "Bu, Nodus veritabanı modudur: Uygulamanıza entegre edilmiş, Notion tarzı bir tablo yöneticisi. Bir dakika içinde size üç örnek veri tabanının yüklü olduğu parçaları göstereceğim. Ayarlar'dan istediğiniz zaman çıkıp eğitimi tekrar izleyebilirsiniz.",
  "Tus bases de datos": "Veritabanlarınız",
  "En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.": "Tüm veritabanlarınız kenar çubuğunda görünür. Her birinin otomatik olarak oluşturulan benzersiz bir tanımlayıcısı vardır. Açmak için birine basın veya yeni bir tane oluşturmak için + düğmesine basın. Burada ayrıca Analiz ve Sohbet bölümleri de bulunmaktadır.",
  "La tabla": "masa",
  "Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.": "Her veritabanı, yazılan sütunlardan oluşan bir tablodur: başlık, metin, sayı, tarih, saat, seçim, çoklu seçim ve onay kutusu. Yukarıda toplam giriş sayısını ve bunların tüm veritabanlarınızın toplamını temsil eden yüzdesini göreceksiniz.",
  "Edita directamente": "Doğrudan düzenle",
  "Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.": "Anında düzenlemek için herhangi bir hücreye tıklayın. Seçim sütunları, anında ekleyebileceğiniz renkli seçenekleri gösterir; Kutular tek tıklamayla kontrol edilir. Silmek için fareyi bir satırın üzerine getirin.",
  "Columnas a tu medida": "Size uygun sütunlar",
  "Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.": "Yeniden adlandırmak, türünü değiştirmek veya seçeneklerini yönetmek için bir sütun başlığına dokunun ve yeni sütunlar eklemek için başlığın sonundaki + düğmesini kullanın. \"Yeni satır\" ile kayıt eklersiniz.",
  "Análisis (próximamente)": "Analiz (çok yakında)",
  "Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.": "Burada bir veritabanı seçebilir ve otomatik istatistiklerin yanı sıra tekrarlanabilir olması için grafikler ve hesaplamaların görüntülendiği yapay zekalı bir rapor alabilirsiniz. Bir sonraki aşamada geliyor.",
  "Chat de datos (próximamente)": "Veri sohbeti (çok yakında)",
  "Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.": "Tekrarlanabilir grafikler ve sorgular oluşturabilen, bir veya daha fazla veri tabanınızla sohbet etmek üzere uyarlanmış bir sohbet. Aynı zamanda bir sonraki aşamaya da varır.",
  "Listo para tus datos": "Verileriniz için hazır",
  "Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.": "Bu örnek verilerle bir gösteridir. Kendi veritabanınızı kullanmaya başlamak istediğinizde kenar çubuğundan bir veritabanı oluşturun ve sütunlarınızı ekleyin. Yakında CSV'yi içe aktarabilecek ve dosyaları toplu olarak yükleyebileceksiniz.",
