  "Heredar modelo principal": "Ana modeli devral",
  "Lleva tus notas, datos de estudio, materiales y grabaciones, borradores, búsquedas guardadas, auditorías de relaciones, bases de datos y Copias protegidas a otro equipo. Al importar se fusiona por fecha: gana la versión más reciente; las eliminaciones de Copias protegidas también se sincronizan mediante borrado lógico.": "Notlarınızı, çalışma verilerinizi, materyallerinizi ve kayıtlarınızı, taslaklarınızı, kayıtlı aramalarınızı, ilişki denetimlerinizi, veritabanlarınızı ve Korumalı Kopyalarınızı başka bir bilgisayara alın. İçe aktarırken tarihe göre birleştirilir: en yeni sürüm kazanır; Korumalı Kopya silme işlemleri aynı zamanda mantıksal silme ile de senkronize edilir.",
  "Esta acción elimina datos de forma permanente. ¿Quieres continuar?": "Bu işlem verileri kalıcı olarak siler. Devam etmek istiyor musun?",
  "Administración del vault de estudio": "Stüdyo Kasası Yönetimi",
  "Comprobaciones locales de SQLite, almacenamiento, índices, huérfanos y papelera.": "Yerel SQLite, depolama, dizinler, yetimler ve çöp denetimleri.",
