  "Paquete": "Paket",
  "Analíticas de estudio desactivadas": "Çalışma analizleri devre dışı bırakıldı",
  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "Bunları Ayarlar → Yapay Zeka Modelleri bölümünden etkinleştirebilirsiniz. İncelemeler yerel olarak çalışmaya devam ediyor.",
  "Modelos de IA": "Yapay zeka modelleri",
  "Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.": "Genel bir model konuşma, analiz, özetleme ve diğer metin görevlerini ele alır. Özel yetenekler aşağıda yapılandırılmıştır.",
  "El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.": "Genel model temel olmaya devam ediyor. Her boş seçici ondan miras alır; Takım modelleri yalnızca geçerli kasaya kaydedilir.",
  "Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.": "Her görev seçilen spesifik modeli kullanır. Takım modelleri yalnızca geçerli kasaya kaydedilir.",
  "Modelo general de texto": "Genel metin modeli",
  "Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.": "Kendi modeli olmayan herhangi bir görevin konuşması, analizi, özetleri ve geri dönüşü.",
  "Conversación, análisis, resúmenes y demás tareas de texto.": "Konuşma, analiz, özetler ve diğer metin görevleri.",
  "Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.": "Bu model, API kredinizi değil abonelik ücretinizi kullanır. Tam bir bütünce analizi, planınızın haftalık veya aylık limitini tüketebilir.",
  "Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.": "Bu yerel model vizyondur ve fikirleri güvenilir bir şekilde çıkarmaz (başıboş dolaşma ve JSON'u kapatmama eğilimindedir). Çıkarma için Gemma 4 E2B'yi veya daha büyük başka bir modeli seçin.",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "Bunlar, Nodus’un yerleşik modelleri arasında elediği ağırlıkların aynısı: fikir çıkarırken başıboş dolaşıyor ve JSON’u hiç kapatmıyorlar. Yine de kullanabilirsiniz, ancak çıkarma için daha büyük bir model daha uygundur.",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "Adım bir neden kaydetmeden başarısız oldu. Yeniden deneyin; yine başarısız olursa modeli Ayarlar → Yapay zekâ modelleri bölümünden kontrol edin.",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "Henüz aralarından seçim yapılacak bir model yok. Sağlayıcılarınızdakileri görmek için «Modelleri yükle» düğmesine basın veya istediklerinizi Ayarlar → Yapay zekâ sağlayıcıları ve modeller bölümünde favori olarak işaretleyin.",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list} yanıt vermedi. Anahtarını veya yerel sunucunun açık olduğunu kontrol edin.",
  "solo visión": "sadece vizyon",
  "Este modelo no puede usarse para extracción de ideas.": "Bu model fikir çıkarmak için kullanılamaz.",
  "Uso mi plan gratuito de este proveedor": "Bu sağlayıcının ücretsiz planını kullanıyorum",
  "Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.": "Taramanın başarısız olmaması için istekleri ücretsiz kullanım sınırlarına göre ayarlayın (çıkış uzunluğunu kesin ve dakika başına sınıra ulaşıldığında bekleyin). Kullanım başına ödeme yapıyorsanız bu seçeneği işaretlemeyin.",
