  "si cambias de modelo, los embeddings creados con el modelo anterior no son compatibles y deberán regenerarse.": "Modeli değiştirirseniz önceki modelle oluşturulan yerleştirmeler uyumlu olmaz ve yeniden oluşturulması gerekir.",
