  "Eliminar modelo": "Modeli sil",
  "Se eliminará «{model}» del almacenamiento de Nodus. Si está seleccionado, las funciones que lo usan dejarán de funcionar hasta que elijas otro modelo o vuelvas a descargarlo.": "“{model}” Nodus depolama alanından kaldırılacak. Seçilirse, onu kullanan özellikler, siz başka bir model seçene veya onu tekrar indirene kadar çalışmayı durduracaktır.",
  "Cambiar modelo de embeddings": "Yerleştirme modelini değiştirme",
  "Los embeddings creados con el modelo anterior no son compatibles con el nuevo. Nodus conservará los datos, pero tendrás que reindexar para que la búsqueda semántica y las relaciones usen el nuevo modelo. ¿Cambiar de todos modos?": "Önceki modelle oluşturulan gömmeler yeni modelle uyumlu değildir. Nodus verileri koruyacaktır ancak anlamsal arama ve ilişkilerin yeni modeli kullanması için yeniden indekslemeniz gerekecektir. Yine de değiştirilsin mi?",
  "Cambiar modelo": "Modeli değiştir",
  "Si cambias de modelo de embeddings, los vectores anteriores no servirán con el nuevo modelo y tendrás que reindexar.": "Gömme modelini değiştirirseniz önceki vektörler yeni modelde çalışmaz ve yeniden indekslemeniz gerekir.",
  "Embeddings multilingües de alta calidad para corpus amplios.": "Büyük derlemler için yüksek kaliteli çok dilli yerleştirmeler.",
  "Embeddings multilingües con contexto largo y buen equilibrio entre precisión y memoria.": "Uzun bağlamlı ve hassasiyet ile hafıza arasında iyi bir denge sağlayan çok dilli yerleştirmeler.",
  "Opción ligera y rápida para equipos con menos memoria.": "Daha az belleğe sahip bilgisayarlar için hafif ve hızlı seçenek.",
  "Modelo visual muy ligero para conversación, resúmenes e ideas.": "Konuşma, özetler ve fikirler için çok hafif görsel model.",
  "Modelo visual de mayor calidad; requiere más almacenamiento y memoria.": "Daha kaliteli görsel model; daha fazla depolama ve hafıza gerektirir.",
  "Modelo visual compacto orientado a documentos e imágenes.": "Belgelere ve resimlere yönelik kompakt görsel model.",
  "Guía esencial de Nodus e IA": "Nodus ve Yapay Zeka İçin Temel Kılavuz",
  "Bóvedas, modelos locales, API keys, costes, embeddings y voz explicados desde cero.": "Kasalar, yerel modeller, API anahtarları, maliyetler, yerleştirmeler ve ses sıfırdan açıklandı.",
