  "Informes didácticos basados en tus materiales, apuntes y transcripciones indexados.": "Dizinlenmiş materyallerinize, notlarınıza ve transkriptlerinize dayalı didaktik raporlar.",
  "El informe enseña el tema paso a paso usando y citando tus materiales de estudio.": "Rapor, çalışma materyallerinizi kullanarak ve alıntı yaparak konuyu adım adım öğretir.",
  "Escribe el tema o pregunta que quieres comprender. El informe explicará los conceptos difíciles, ejemplos y conexiones usando tus materiales.": "Anlamak istediğiniz konuyu veya soruyu yazın. Rapor, materyallerinizi kullanarak zor kavramları, örnekleri ve bağlantıları açıklayacaktır.",
