  "Opcional. Añade una transcripción o texto que deba ser buscable e indexado…": "İsteğe bağlı. Aranabilir ve dizine eklenmesi gereken bir transkript veya metin ekleyin…",
  "Si el archivo permite extraer texto automáticamente, Nodus lo hará al guardarlo. Este campo permite añadirlo o sustituirlo manualmente.": "Dosya otomatik metin çıkarmaya izin veriyorsa Nodus bunu kaydederken yapacaktır. Bu alan manuel olarak eklemenizi veya değiştirmenizi sağlar.",
