  "Elige archivos o una carpeta completa. Nodus empareja cada archivo con su fila por el nombre exacto y, si no, por el código del catálogo que compartan (LV001-FG001).": "Dosyaları veya bir klasörün tamamını seçin. Nodus, her dosyayı kendi satırıyla tam isme göre, değilse de paylaştıkları katalog koduna (LV001-FG001) göre eşleştirir.",
