  "Al aplicarlo se reemplazará la estructura actual del cuaderno.": "Bunu uygulamak mevcut not defteri yapısının yerini alacaktır.",
  "Importar de mi guía docente": "Öğretim rehberimden içe aktar",
  "Nota mínima para promediar: {min}": "Minimum nottan ortalamaya: {min}",
  "Pega el apartado de evaluación. La IA propone la estructura; tú la confirmas. Nunca calcula notas.": "Değerlendirme bölümünü yapıştırın. Yapay zeka yapıyı öneriyor; siz onaylayın. Asla notları hesaplamaz.",
