  "{n} con vídeo": "{n} videolu",
  "Selecciona una presentación": "Bir sunum seçin",
  "Elige una presentación de la lista para ver sus diapositivas, o importa un PDF nuevo.": "Slaytlarını görüntülemek için listeden bir sunum seçin veya yeni bir PDF'yi içe aktarın.",
  "Eliminar presentación": "Sunuyu sil",
  "¿Seguro que quieres eliminar «{name}»? Esta acción no se puede deshacer.": "“{name}” ifadesini silmek istediğinizden emin misiniz? Bu eylem geri alınamaz.",
  "Sin cargar": "Yüklemeden",
  "Vídeos": "Videolar",
