  "El PowerPoint tiene {pptx} diapositivas y el PDF tiene {pdf}. Deben coincidir para importar las notas.": "PowerPoint'te {pptx} slayt var ve PDF'de {pdf} var. Notları içe aktarmak için eşleşmeleri gerekir.",
