  "El TXT tiene {txt} diapositivas y el PDF tiene {pdf}. Deben coincidir para importar las notas.": "TXT'de {txt} slayt var ve PDF'de {pdf} var. Notları içe aktarmak için eşleşmeleri gerekir.",
  "El archivo TXT de notas no tiene un formato válido.": "Notların TXT dosyası geçerli bir formatta değil.",
