  'Semilla visual': 'Görsel çekirdek',
  'Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.': 'Bu karakter için ürettiğin TÜM görsellere eklenen kısa ve değişmez bir metin. Karakterin bir görselden diğerine kendine benzemesini sağlayan şey budur; bu yüzden olabildiğince az değiştir.',
  'p. ej. «semielfo de rasgos afilados, pelo negro recogido, ojos ámbar»': 'ör. “keskin hatlı yarı elf, toplanmış siyah saç, kehribar gözler”',
