  'Arrastra la imagen para encuadrarla y usa el zoom.': 'Görseli çerçevelemek için sürükle ve yakınlaştırmayı kullan.',
  'Retrato con IA': 'Yapay zekâ portresi',
  'Se usa la apariencia y la semilla visual de la ficha, así que el personaje mantiene el mismo aspecto entre imágenes.': 'Künyedeki görünüş ve görsel çekirdek kullanılır, böylece karakter görseller arasında aynı görünür.',
  'Escribe primero la apariencia del personaje en la sección Descripción.': 'Önce Betimleme bölümünde karakterin görünüşünü yaz.',
  'Solo para esta imagen: pose, gesto, ropa, luz… (opcional)': 'Yalnızca bu görsel için: duruş, jest, giysi, ışık… (isteğe bağlı)',
  'Tu mundo': 'Dünyan',
  'Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.': 'Bir kurgu dünyasını parça parça kur. Karakterlerden başla: adları ve rumuzları, yaşamlarındaki olaylar, bağları ve betimlemeleri; işine yaradığında üretebileceğin portreler ve yaşam öyküleriyle.',
