  'Lo que ocurre en la escena, en tus palabras.': 'Sahnede ne olduğu, kendi sözlerinle.',
  'Quién quiere qué, quién se lo impide y cómo acaba…': 'Kim ne istiyor, kim engelliyor ve nasıl bitiyor…',
