  'Añadir personaje a la escena': 'Sahneye karakter ekle',
  'Crea antes algún personaje.': 'Önce bir karakter oluştur.',
  '¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.': 'Bu sahne silinsin mi? İçinde görünen karakterler silinmez.',
  'El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.': 'Yıl, dünyada ne zaman olduğudur; sıra ise anlatıda nereye düştüğü. Yüzyıllar öncesinde geçen bir önsöz anlatıda ilk, kronolojide sondur.',
  'Apariciones': 'Görünüşler',
  'En orden del relato, no de la cronología.': 'Anlatının sırasına göre, kronolojinin değil.',
  'Secretos': 'Sırlar',
  'Añadir secreto': 'Sır ekle',
