  'Revelado': 'Açığa çıktı',
  'Además sabe': 'Ayrıca biliyor',
  'Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.': 'Her zaman kaynaklarına dayanarak öğretmen için üniteler veya öğrencilere dağıtılacak ders notları tasarla.',
  'Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.': 'Dersi vermek için bir plan ile dağıtıma hazır ders notları arasında seçim yap.',
  'Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.': 'Öğrenmeye yönelik ders notları ile konuyu öğretmeye yönelik bir plan arasında seçim yap.',
  'Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.': 'Hazırlamak istediğin konuyu veya dersi yaz. Rapor, materyallerini kullanarak hedefleri, sırayı, etkinlikleri ve değerlendirmeyi tasarlayacak.',
  'Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.': 'Ders notlarının konusunu yaz. Rapor, materyallerini kullanarak konuyu örnekler ve öz değerlendirmeyle adım adım açıklayacak.',
  'Público objetivo y producto': 'Hedef kitle ve ürün',
  'Docente · planificación de la lección': 'Öğretmen · ders planı',
  'Alumnado · apuntes para entregar': 'Öğrenciler · dağıtıma hazır notlar',
  'Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.': 'Öğretmen için hedefler, sıra, etkinlikler, anlama kontrolleri ve değerlendirme oluşturur.',
  'Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.': 'Öğrencilere yönelik açıklamalar, tanımlar, örnekler, özetler ve öz değerlendirme oluşturur.',
  'En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.': '“Oluştur” bölümündeki Öğretim üniteleri artık materyallerinden öğretmen planı veya öğrenci notları üretebilir. Diğer noktalı bölümler önerilerine açık kalmaya devam ediyor. Bu öğreticiyi Ayarlar’dan yeniden başlatabilirsin.',
