  'Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.': 'Makaleler karakter, yer veya hizip olmayan her şey içindir: büyü, bir din, bir dil, bir yaratık, bir nesne. Geri kalan her şey ansiklopedide zaten kendiliğinden yer alır.',
