  'reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos': 'dünya kuralları, çatışmalar, anlatı yayları, tutarlılık, açık sorular, olay örgüleri ve el yazmaları',
  'En la enciclopedia': 'Ansiklopedide',
  '{count} sin desarrollar': '{count} geliştirilmemiş',
  'Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].': 'Kurgusal bir dünyayı parça parça inşa et: karakterler, yerler, hizipler, kültürler, sahneler ve haritalar. Ansiklopedi hepsini tek bir dizinde toplar ve dünyanın geri kalanını — büyüyü, bir dini, bir dili — [[çift köşeli parantez]] ile bağlayarak yazmana izin verir.',
  'Analizar el mundo': 'Dünyayı analiz et',
  'Aparecen a menudo y no están definidos': 'Sık geçiyor ve tanımlı değil',
  'Esto es una sospecha, no un hecho: son nombres que se repiten en tus textos.': 'Bu bir sezgi, bir olgu değil: metinlerinde yinelenen adlar.',
  'Lo escribiste tú entre dobles corchetes, así que ya existen en tu mundo.': 'Onları çift köşeli parantez içinde kendin yazdın, yani dünyanda zaten varlar.',
