  "Nodus Browser no abre este tipo de dirección": "Nodus Browser bu tür bir adresi açmaz",
  "Esta página dejó de responder": "Bu sayfa yanıt vermeyi durdurdu",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Dikkat: tarayıcınızda oturum açarsanız oturum orada kalır. Nodus içinde {host} sitesinde hâlâ oturumunuz açılmamış olacak, çünkü çerezler tarayıcılar arasında paylaşılmaz.",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Dikkat: tarayıcınızda oturum açarsanız oturum orada kalır. Nodus içinde Google oturumunuz hâlâ açılmamış olacak, çünkü çerezler tarayıcılar arasında paylaşılmaz.",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "{host} parola veya e-posta bağlantısıyla girişi kabul ediyorsa, o yol burada çalışır ve Nodus oturumu hatırlar.",
  "Volver e intentar con contraseña": "Geri dön ve parolayla dene",
  "Usar {host} en mi navegador": "{host} sitesini tarayıcımda kullan",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "Nodus’un Gmail’inizi veya Drive’ınızı okuması için başka bir şey gerekir: hesabı Ayarlar’dan bağlamak — Google’ın masaüstü uygulamalarına izin verdiği yol. Henüz kullanılabilir değil.",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "Bu bir Nodus hatası değil: Google, başka bir uygulamanın içine gömülü her tarayıcıdan oturum açmayı reddediyor.",
  "Google no permite iniciar sesión desde un navegador integrado": "Google, gömülü bir tarayıcıdan oturum açmaya izin vermiyor",
  "Abrir en tu navegador": "Tarayıcınızda aç",
