  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "Çerezleri silmek, oturum açtığınız sitelerdeki oturumunuzu kapatır.",
  "También se cerrarán todas las pestañas abiertas del navegador.": "Açık tüm tarayıcı sekmeleri de kapatılır.",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium çerezleri kaydedilebilir alan adına göre siler: bir alt alan adının çerezlerini silmek ana alan adınınkileri ve diğer alt alan adlarınınkileri de siler.",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus önbelleği ve profilin toplam boyutunu ölçebilir. Chromium her depolama kategorisinin boyutunu ayrı ayrı bildirmediğinden diğerleri etkilenen site sayısıyla gösterilir.",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser, uygun yerlerde oturumunuz açık kalsın diye çerezleri ve site depolamasını saklar. Nodus kullanıcı adı veya parola saklamaz ve parola yöneticisi içermez.",
